head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


target;
stime;
calendar;
objType = ""; // mask Or edit
document.writeln('<div id="minical" onmouseover="Calendar_Over()" onmouseout="Calendar_Out()" style="background: buttonface; margin:2; border: 1 solid buttonshadow; width:160; display:none; position:absolute; z-index:1">');
document.writeln('<iframe id="Cal_iFrame" width=160 height=130 src=../js/cal.html scrolling=no frameborder=no border=1 bordercolor=red></iframe>');
document.writeln('</div>');
/**
 * @method
 * @name Calendar_Over
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Calendar_Over = function() {
    window.clearTimeout(scwin.stime);
};
/**
 * @method
 * @name Calendar_Out
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Calendar_Out = function() {
    scwin.stime = window.setTimeout("calendar.style.display='none';", 200);
};
/**
 * @method
 * @name Calendar_Click
 * @description desc
 * @param {string} e desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Calendar_Click = function(e) {
    cal_Day = e.title;
    if (cal_Day.length > 6) {
        target.setValue(cal_Day);
        //		target.value = cal_Day

    }
    calendar.style.display = 'none';
};
/**
 * @method
 * @name Calendar_D
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Calendar_D = function(obj) {
    scwin.objType = (typeof(obj.getValue()) == "undefined") ? "mask" : "edit";
    if (scwin.objType == "edit") {
        alert("mask를 사용하세요.");
        return;
    }
    scwin.target = obj;
    var now = new Array(0);
    if (obj.getText() == "") {

    } else {
        now = new Array(3); //obj.text.split("-");
        now[0] = obj.text.substring(0, 4);
        now[1] = obj.text.substring(4, 6);
        now[2] = obj.text.substring(6, 8);
    }
    //	alert(obj.text + ", " + now[0] + ", " + now[1] + ", " + now[2]);
    var top = document.body.clientTop + scwin.GetObjectTop(obj);
    var left = document.body.clientLeft + scwin.GetObjectLeft(obj);
    scwin.calendar = document.all.minical;
    calendar.style.pixelTop = top + obj.offsetHeight;
    calendar.style.pixelLeft = left;
    calendar.style.display = '';
    if (now.length == 3) {
        Cal_iFrame.Show_cal(now[0], now[1], now[2]);
    } else {
        now = new Date();
        Cal_iFrame.Show_cal(now.getFullYear(), now.getMonth() + 1, now.getDate());
    }
};


