/**
	HTML 개체용 유틸리티 함수
**/
/**
 * @method
 * @name GetObjectTop
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.GetObjectTop = function(obj) {
    if (obj.offsetParent == document.body) return obj.offsetTop;

    else return obj.offsetTop + scwin.GetObjectTop(obj.offsetParent);
};
/**
 * @method
 * @name GetObjectLeft
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.GetObjectLeft = function(obj) {
    if (obj.offsetParent == document.body) return obj.offsetLeft;

    else return obj.offsetLeft + scwin.GetObjectLeft(obj.offsetParent);
};
